<script setup lang="ts">
import {computed,ref,onMounted} from 'vue'
import {Users,ListTodo,CalendarCheck,ArrowUpRight,PhoneCall,UserRoundCheck,ArrowRight,Sun,RefreshCw,CheckCircle2,ChevronDown} from 'lucide-vue-next'
const props=defineProps<{workspace:string;role:string;summary:any;username:string;request:(path:string)=>Promise<any>}>()
defineEmits<{navigate:[value:string];refresh:[]}>()
const assurance=computed(()=>props.workspace==='assurance')
const metrics=computed(()=>[
 {label:assurance.value?'Contacts dans votre périmètre':'Prospects dans votre périmètre',value:props.summary.contacts??props.summary.prospects??0,icon:Users,tone:'olive'},
 assurance.value?{label:props.role==='advisor'?'Comptes rendus attendus':'Tâches de suivi ouvertes',value:props.role==='advisor'?props.summary.reports_due:props.summary.open_follow_ups,icon:props.role==='advisor'?CalendarCheck:ListTodo,tone:'purple'}:
 {label:props.role==='client'?'Visites à venir':'Rappels arrivés à échéance',value:props.role==='client'?props.summary.upcoming:props.summary.callbacks_due,icon:props.role==='client'?CalendarCheck:PhoneCall,tone:'purple'},
 ...(!assurance.value&&props.role==='administrator'?[{label:'Prospects sans affectation',value:props.summary.unassigned,icon:UserRoundCheck,tone:'orange'}]:[])
])
const upcoming=ref<any[]>([]),loading=ref(true),error=ref('')
async function loadUpcoming(){loading.value=true;error.value='';try{const data=await props.request(assurance.value?'appointments/?period=upcoming&status=scheduled':'visits/?period=upcoming');upcoming.value=data.results.filter((row:any)=>row.status==='scheduled').slice(0,3)}catch(e:any){error.value=e.message}finally{loading.value=false}}
function date(row:any){return new Intl.DateTimeFormat('fr-FR',{timeZone:row.timezone||'America/Toronto',day:'numeric',month:'short',hour:'2-digit',minute:'2-digit'}).format(new Date(row.starts_at))}
onMounted(loadUpcoming)
</script>
<template>
 <section v-if="role==='setter'" class="setter-homepage">
  <header class="home-welcome"><div><span class="home-eyebrow"><Sun :size="16"/>VOTRE ESPACE {{assurance?'ASSURANCE':'ISOLATION'}}</span><h1>Bonjour {{username}} <span class="hello-hand" aria-hidden="true">👋</span></h1><p>Vos prospects, vos prochaines actions. Tout commence ici.</p></div><button class="home-refresh" :disabled="loading" @click="$emit('refresh');loadUpcoming()"><RefreshCw :size="16"/>Actualiser</button></header>
  <div class="home-highlights">
   <button class="home-highlight blue" @click="$emit('navigate','contacts')"><span class="highlight-icon"><Users :size="23"/></span><span><span class="highlight-label">Mes prospects</span><strong>{{summary.contacts??summary.prospects??0}}</strong><small>Retrouver mes fiches<ArrowRight :size="14"/></small></span></button>
   <button class="home-highlight peach" @click="$emit('navigate',assurance?'followups':'contacts')"><span class="highlight-icon"><component :is="assurance?ListTodo:PhoneCall" :size="23"/></span><span><span class="highlight-label">{{assurance?'Tâches à traiter':'Rappels à traiter'}}</span><strong>{{(assurance?summary.open_follow_ups:summary.callbacks_due)??0}}</strong><small>{{assurance?'Ouvrir mes tâches':'Ouvrir mes prospects'}}<ArrowRight :size="14"/></small></span></button>
   <div class="home-highlight mint"><span class="highlight-icon"><CalendarCheck :size="23"/></span><span><span class="highlight-label">Mon prochain créneau</span><strong class="next-slot">{{loading?'Chargement…':error?'Agenda indisponible':upcoming.length?date(upcoming[0]):'Aucun prévu'}}</strong><small>{{!loading&&!error&&!upcoming.length?'Aucun créneau à venir':'Consultez le détail dans votre agenda'}}</small></span></div>
  </div>
  <div class="home-body">
   <section class="home-start"><header><span class="section-kicker">PASSER À L’ACTION</span><h2>Par quoi commencer ?</h2><p>Un accès direct à l’essentiel de votre journée.</p></header>
    <button class="home-action" @click="$emit('navigate','contacts')"><span class="home-action-icon blue"><Users :size="22"/></span><span><strong>Retrouver un prospect</strong><small>Consultez sa fiche et préparez votre prochain échange.</small></span><ArrowRight :size="19"/></button>
    <button class="home-action" @click="$emit('navigate','appointments')"><span class="home-action-icon lavender"><CalendarCheck :size="22"/></span><span><strong>{{assurance?'Organiser mes rendez-vous':'Organiser mes visites'}}</strong><small>Retrouvez vos créneaux et suivez vos réservations.</small></span><ArrowRight :size="19"/></button>
    <button v-if="assurance" class="home-action" @click="$emit('navigate','followups')"><span class="home-action-icon peach"><ListTodo :size="22"/></span><span><strong>Avancer sur mes tâches</strong><small>Traitez vos suivis et vos prochaines échéances.</small></span><ArrowRight :size="19"/></button>
   </section>
   <aside class="home-agenda"><header><div><span class="section-kicker">À VENIR</span><h2>{{assurance?'Mes rendez-vous':'Mes visites'}}</h2></div><span class="agenda-symbol"><CalendarCheck :size="22"/></span></header>
    <p v-if="loading" role="status" class="agenda-feedback">Chargement de votre agenda…</p>
    <div v-else-if="error" role="alert" class="agenda-feedback"><p>{{error}}</p><button class="home-refresh" @click="loadUpcoming">Réessayer</button></div>
    <div v-else-if="!upcoming.length" class="agenda-empty"><span><CheckCircle2 :size="28"/></span><h3>De la place pour la suite</h3><p>Aucun {{assurance?'rendez-vous':'créneau'}} à venir pour le moment.</p></div>
    <ol v-else class="home-upcoming"><li v-for="row in upcoming" :key="row.id"><span class="appointment-dot"></span><div><time>{{date(row)}}</time><strong>{{(assurance?row.contact:row.prospect)?.name||'Dossier sans nom'}}</strong><small>{{row.timezone||'America/Toronto'}}</small></div></li></ol>
    <button class="home-agenda-link" @click="$emit('navigate','appointments')">Ouvrir mon agenda<ArrowRight :size="17"/></button>
   </aside>
  </div>
  <details v-if="assurance" class="home-followup-details"><summary><span class="followup-summary-icon"><ListTodo :size="19"/></span><span><strong>Rappels et notifications</strong><small>Consulter le détail de mes suivis</small></span><ChevronDown :size="19"/></summary><div class="home-followup-content"><slot/></div></details>
 </section>
 <section v-else class="crm-overview">
  <div class="crm-metrics"><div v-for="metric in metrics" :key="metric.label" class="crm-metric"><span class="metric-icon" :class="metric.tone"><component :is="metric.icon" :size="20"/></span><div><p>{{metric.label}}</p><strong>{{metric.value??0}}</strong></div></div></div>
  <div class="crm-overview-grid"><section class="crm-priorities"><div class="overview-section-title"><h3>Votre activité</h3><span>{{workspace==='assurance'?'Assurance':'Isolation'}}</span></div><button class="overview-action" @click="$emit('navigate','contacts')"><span class="action-icon"><Users :size="20"/></span><span><strong>{{role==='client'?'Consulter mes dossiers':'Retrouver mes contacts'}}</strong><small>{{role==='client'?'Voir les visites et les setters à l’origine des réservations.':'Ouvrir les fiches, qualifier et préparer les prochains échanges.'}}</small></span><ArrowUpRight :size="18"/></button><button v-if="role!=='client'" class="overview-action" @click="$emit('navigate','appointments')"><span class="action-icon purple"><CalendarCheck :size="20"/></span><span><strong>{{assurance?'Gérer les rendez-vous':'Gérer les visites'}}</strong><small>Consulter les créneaux et suivre les comptes rendus.</small></span><ArrowUpRight :size="18"/></button><button v-if="assurance&&role!=='advisor'" class="overview-action" @click="$emit('navigate','followups')"><span class="action-icon orange"><ListTodo :size="20"/></span><span><strong>Traiter les tâches de suivi</strong><small>Retrouver les actions ouvertes et les prochaines échéances.</small></span><ArrowUpRight :size="18"/></button></section><aside class="crm-workspace-note"><span class="note-tag">VOTRE AGENDA</span><h3>{{assurance?'Prochains rendez-vous':'Prochaines visites'}}</h3><p v-if="loading">Chargement de l’agenda…</p><p v-else-if="error" role="alert">{{error}} <button class="secondary" @click="loadUpcoming">Réessayer</button></p><p v-else-if="!upcoming.length">Aucun créneau à venir dans votre périmètre.</p><ol v-else class="upcoming-list"><li v-for="row in upcoming" :key="row.id"><span>{{date(row)}}</span><strong>{{(assurance?row.contact:row.prospect)?.name||'Dossier sans nom'}}</strong></li></ol><button class="agenda-link" @click="$emit('navigate','appointments')">Ouvrir l’agenda<ArrowUpRight :size="16"/></button></aside></div>
  <div class="crm-dashboard-details"><slot/></div>
 </section>
